import { FunctionComponent } from 'preact';
import { HTMLAttributes } from 'preact/compat';
import { Button, Icon } from '@adobe-commerce/elsie/components';
import { Trash, Minus } from '@adobe-commerce/elsie/icons';
import '@/requisitionList/components/BatchActions/BatchActions.css';
import { useText } from '@adobe-commerce/elsie/i18n';

export interface BatchActionsProps
  extends HTMLAttributes<HTMLDivElement | HTMLFormElement> {
  selectedItems: Set<string>;
  deletingItemId: string | null;
  addingToCartItemId: string | null;
  bulkAddingToCart: boolean;
  updatingQuantityItemId: string | null;
  bulkMovingToList?: boolean;
  bulkCopyingToList?: boolean;
  onSelectAll: () => void;
  onSelectNone: () => void;
  onBulkAddToCart: () => void;
  onBulkDelete: () => void;
  onBulkMoveToList?: () => void;
  onBulkCopyToList?: () => void;
}

export const BatchActions: FunctionComponent<BatchActionsProps> = ({
  selectedItems,
  deletingItemId,
  addingToCartItemId,
  bulkAddingToCart,
  updatingQuantityItemId,
  bulkMovingToList = false,
  bulkCopyingToList = false,
  onSelectAll,
  onSelectNone,
  onBulkAddToCart,
  onBulkDelete,
  onBulkMoveToList,
  onBulkCopyToList,
}) => {
  const translations = useText({
    statusDeleting: `RequisitionList.RequisitionListView.statusDeleting`,
    actionSelectAll: `RequisitionList.RequisitionListView.actionSelectAll`,
    actionSelectNone: `RequisitionList.RequisitionListView.actionSelectNone`,
    actionAddToCart: `RequisitionList.RequisitionListView.actionAddToCart`,
    actionDeleteSelectedItems: `RequisitionList.RequisitionListView.actionDeleteSelectedItems`,
    statusBulkAddingToCart: `RequisitionList.RequisitionListView.statusBulkAddingToCart`,
    actionMoveToList: `RequisitionList.RequisitionListView.actionMoveToList`,
    actionCopyToList: `RequisitionList.RequisitionListView.actionCopyToList`,
  });

  const isDisabled =
    deletingItemId !== null ||
    addingToCartItemId !== null ||
    bulkAddingToCart ||
    updatingQuantityItemId !== null ||
    bulkMovingToList ||
    bulkCopyingToList;

  const hasSelectedItems = selectedItems.size > 0;

  return (
    <div className="requisition-list-view__batch-actions">
      <div className="requisition-list-view__batch-actions-left">
        <button
          data-testid="bulk-actions-select-toggle-btn"
          type="button"
          className={`requisition-list-view__batch-actions-select-toggle ${
            hasSelectedItems
              ? 'requisition-list-view__batch-actions-select-toggle--active'
              : ''
          }`}
          onClick={hasSelectedItems ? onSelectNone : onSelectAll}
          disabled={isDisabled}
          aria-label={
            hasSelectedItems
              ? translations.actionSelectNone
              : translations.actionSelectAll
          }
        >
          <Icon source={Minus} />
        </button>
        <button
          type="button"
          className="requisition-list-view__batch-actions-select-label"
          onClick={hasSelectedItems ? onSelectNone : onSelectAll}
          disabled={isDisabled}
        >
          {translations.actionSelectAll}
        </button>
      </div>

      {hasSelectedItems && (
        <div className="requisition-list-view__batch-actions-buttons">
          <span
            className="requisition-list-view__batch-actions-count-badge"
            aria-label={`${selectedItems.size} items selected`}
          >
            {selectedItems.size}
          </span>
          {onBulkMoveToList && (
            <Button
              data-testid="bulk-actions-move-to-list-btn"
              type="button"
              variant="secondary"
              onClick={onBulkMoveToList}
              disabled={isDisabled}
            >
              {translations.actionMoveToList}
            </Button>
          )}
          {onBulkCopyToList && (
            <Button
              data-testid="bulk-actions-copy-to-list-btn"
              type="button"
              variant="secondary"
              onClick={onBulkCopyToList}
              disabled={isDisabled}
            >
              {translations.actionCopyToList}
            </Button>
          )}
          <Button
            data-testid="bulk-actions-add-to-cart-btn"
            type="button"
            variant="secondary"
            onClick={onBulkAddToCart}
            disabled={isDisabled}
          >
            {bulkAddingToCart
              ? translations.statusBulkAddingToCart
              : translations.actionAddToCart}
          </Button>
          <button
            data-testid="bulk-actions-delete-btn"
            type="button"
            className="requisition-list-view__batch-actions-delete-icon"
            onClick={onBulkDelete}
            disabled={isDisabled}
            aria-label={translations.actionDeleteSelectedItems}
          >
            <Icon source={Trash} />
          </button>
        </div>
      )}
    </div>
  );
};
