import { useState, useEffect, useCallback } from 'preact/hooks';
import { Container } from '@adobe-commerce/elsie/lib';
import { useText } from '@adobe-commerce/elsie/i18n';
import {
  getCompanyUsers,
  CompanyUser,
} from '@/requisitionList/api/getCompanyUsers';
import {
  shareRequisitionListByToken,
  ShareRequisitionListByTokenResult,
} from '@/requisitionList/api/shareRequisitionListByToken';
import { ShareRequisitionListByEmailError } from '@/requisitionList/api/shareRequisitionListByEmail';
import { ShareRequisitionListContent as ShareRequisitionListContentComponent } from '@/requisitionList/components/ShareRequisitionListContent/ShareRequisitionListContent';
import { state } from '@/requisitionList/lib/state';

export interface ShareRequisitionListContentProps {
  requisitionListUid: string;
  isSubmitting: boolean;
  onSubmit: (
    customerUids: string[]
  ) => Promise<Array<ShareRequisitionListByEmailError> | null>;
  currentCustomerEmail?: string;
  /**
   * Called with the already-built relative share URL to allow customization (e.g. making it absolute).
   * Example: (relativeUrl) => `${window.location.origin}${relativeUrl}`
   * Falls back to using the relative URL as-is, built from the storefront path in store config.
   */
  routeSharedRequisitionList?: (relativeUrl: string) => string;
}

export const ShareRequisitionListContent: Container<
  ShareRequisitionListContentProps
> = ({
  requisitionListUid,
  isSubmitting,
  onSubmit,
  currentCustomerEmail,
  routeSharedRequisitionList,
}: ShareRequisitionListContentProps) => {
  const translations = useText({
    emailInstruction:
      'RequisitionList.ShareRequisitionListContent.emailInstruction',
    emailLabel: 'RequisitionList.ShareRequisitionListContent.emailLabel',
    emailPlaceholder:
      'RequisitionList.ShareRequisitionListContent.emailPlaceholder',
    submitLabel: 'RequisitionList.ShareRequisitionListContent.submitLabel',
    linkInstruction:
      'RequisitionList.ShareRequisitionListContent.linkInstruction',
    copyLink: 'RequisitionList.ShareRequisitionListContent.copyLink',
    linkCopied: 'RequisitionList.ShareRequisitionListContent.linkCopied',
    loadingUsers:
      'RequisitionList.ShareRequisitionListContent.loadingUsers',
    loadingLink:
      'RequisitionList.ShareRequisitionListContent.loadingLink',
    noUsersAvailable:
      'RequisitionList.ShareRequisitionListContent.noUsersAvailable',
    usersLoadError:
      'RequisitionList.ShareRequisitionListContent.usersLoadError',
    maxRecipientsValidation:
      'RequisitionList.ShareRequisitionListContent.maxRecipientsValidation',
    shareSuccessMessage:
      'RequisitionList.ShareRequisitionListContent.shareSuccessMessage',
  });

  const [companyUsers, setCompanyUsers] = useState<CompanyUser[]>([]);
  const [loadingUsers, setLoadingUsers] = useState(true);
  const [usersLoadFailed, setUsersLoadFailed] = useState(false);
  const [selectedUids, setSelectedUids] = useState<Set<string>>(new Set());

  const [shareLink, setShareLink] = useState<string | null>(null);
  const [loadingLink, setLoadingLink] = useState(true);
  const [linkErrorMessage, setLinkErrorMessage] = useState<string | null>(null);
  const [linkCopied, setLinkCopied] = useState(false);
  const [selectionError, setSelectionError] = useState<string | null>(null);
  const [submitErrorMessage, setSubmitErrorMessage] = useState<string | null>(
    null
  );
  const [isShareSuccess, setIsShareSuccess] = useState(false);
  const [sharedRecipientEmails, setSharedRecipientEmails] = useState<string[]>(
    []
  );

  const maxRecipients = (() => {
    const configValue = state.config?.requisition_list_share_max_recipients;
    const parsed = Number(configValue);
    return Number.isFinite(parsed) && parsed > 0 ? parsed : null;
  })();

  useEffect(() => {
    getCompanyUsers()
      .then((users: CompanyUser[]) => {
        const colleagues = users.filter((user) => {
          if (
            currentCustomerEmail &&
            user.email.toLowerCase() === currentCustomerEmail.toLowerCase()
          ) {
            return false;
          }
          return true;
        });
        setCompanyUsers(colleagues);
      })
      .catch(() => {
        setUsersLoadFailed(true);
      })
      .finally(() => setLoadingUsers(false));
  }, [currentCustomerEmail]);

  useEffect(() => {
    shareRequisitionListByToken(requisitionListUid)
      .then((result: ShareRequisitionListByTokenResult) => {
        if (result.token) {
          const storefrontPath =
            state.config?.requisition_list_share_storefront_path ?? '';
          const relativeUrl = `/${storefrontPath}?requisition_id=${result.token}`;
          const shareLink = routeSharedRequisitionList
            ? routeSharedRequisitionList(relativeUrl)
            : relativeUrl;
          setShareLink(shareLink);
        } else {
          setShareLink(null);
        }
        setLinkErrorMessage(result.errorMessage);
      })
      .finally(() => setLoadingLink(false));
  }, [requisitionListUid, routeSharedRequisitionList]);

  const handleSubmit = useCallback(async () => {
    const selectedIds = Array.from(selectedUids);
    const selectedEmails = companyUsers
      .filter((user) => selectedIds.includes(String(user.id)))
      .map((user) => user.email);

    const errors = await onSubmit(selectedIds);
    if (!errors) {
      setIsShareSuccess(true);
      setSharedRecipientEmails(selectedEmails);
      setSubmitErrorMessage(null);
    } else {
      setSubmitErrorMessage(errors[0]?.message || null);
    }
  }, [selectedUids, companyUsers, onSubmit]);

  const handleCopyLink = useCallback(() => {
    navigator.clipboard.writeText(shareLink!).then(
      () => {
        setLinkCopied(true);
        setTimeout(() => setLinkCopied(false), 3000);
      },
      (err) => {
        console.error('Failed to copy share link to clipboard:', err);
      }
    );
  }, [shareLink]);

  const multiSelectOptions = companyUsers.map((user) => ({
    label: `${user.firstname} ${user.lastname} (${user.email})`,
    value: user.id,
  }));

  const usersErrorMessage = usersLoadFailed ? translations.usersLoadError : null;

  const canSubmit = !isSubmitting && selectedUids.size > 0 && !selectionError;

  return (
    <ShareRequisitionListContentComponent
      loadingUsers={loadingUsers}
      usersErrorMessage={usersErrorMessage}
      loadingLink={loadingLink}
      selectedUserValues={Array.from(selectedUids)}
      multiSelectOptions={multiSelectOptions}
      shareLink={shareLink}
      linkErrorMessage={linkErrorMessage}
      linkCopied={linkCopied}
      isSubmitting={isSubmitting}
      canSubmit={canSubmit}
      onSubmitClick={handleSubmit}
      onCopyLinkClick={handleCopyLink}
      onUsersFieldInteract={() => {
        if (selectionError) {
          setSelectionError(null);
        }
        if (submitErrorMessage) {
          setSubmitErrorMessage(null);
        }
      }}
      onSelectedUsersChange={(values: Array<string | number>) => {
        const nextValues = values.map(String);
        if (maxRecipients && nextValues.length > maxRecipients) {
          setSelectionError(
            translations.maxRecipientsValidation.replace(
              '{max}',
              String(maxRecipients)
            )
          );
          return;
        }
        setSelectionError(null);
        setSelectedUids(new Set(nextValues));
      }}
      selectionError={selectionError}
      submitErrorMessage={submitErrorMessage}
      isShareSuccess={isShareSuccess}
      sharedRecipientEmails={sharedRecipientEmails}
    />
  );
};
