import { FunctionComponent } from 'preact';
import { useState } from 'preact/compat';
import { Button, Card, Icon } from '@adobe-commerce/elsie/components';
import { List } from '@adobe-commerce/elsie/icons';
import { RequisitionList } from '@/requisitionList/data/models/requisitionList';
import { useRequisitionLists } from '@/requisitionList/hooks/useRequisitionLists';
import '@/requisitionList/components/RequisitionListPicker/RequisitionListPicker.css';

export interface RequisitionListPickerProps {
  excludeUid?: string;
  confirmLabel: string;
  disabled?: boolean;
  onConfirm: (selectedUid: string) => void;
}

export const RequisitionListPicker: FunctionComponent<
  RequisitionListPickerProps
> = ({ excludeUid, confirmLabel, disabled = false, onConfirm }) => {
  const { lists } = useRequisitionLists();
  const [selectedUid, setSelectedUid] = useState<string | null>(null);

  const filteredLists = excludeUid
    ? lists.filter((list: RequisitionList) => list.uid !== excludeUid)
    : lists;

  return (
    <Card variant="secondary">
      <form
        onSubmit={(e: Event) => {
          e.preventDefault();
          if (selectedUid) onConfirm(selectedUid);
        }}
        className="requisition-list-picker__form"
      >
        <div className="requisition-list-picker__available-lists">
          {filteredLists.map((list: RequisitionList) => (
            <Card
              key={list.uid}
              variant={selectedUid === list.uid ? 'primary' : 'secondary'}
              onClick={() => setSelectedUid(list.uid)}
            >
              <Icon source={List} />
              <span>{list.name}</span>
            </Card>
          ))}
        </div>
        <div className="requisition-list-picker__actions">
          <Button type="submit" disabled={!selectedUid || disabled}>
            {confirmLabel}
          </Button>
        </div>
      </form>
    </Card>
  );
};
