import {
  HTMLAttributes,
  useCallback,
  useEffect,
  useMemo,
  useState,
} from 'preact/compat';
import { events } from '@adobe-commerce/event-bus';
import { Container } from '@adobe-commerce/elsie/lib';
import { RequisitionList } from '../../data/models/requisitionList.js';
import { Item } from '@/requisitionList/data/models/item';
import {
  Button,
  Card,
  Icon,
  InLineAlert,
} from '@adobe-commerce/elsie/components';
import { addProductsToRequisitionList } from '@/requisitionList/api/addProductsToRequisitionList/addProductsToRequisitionList';
import {
  EmptyList,
  RequisitionListModal,
  RequisitionListActions,
  RequisitionListPicker,
} from '@/requisitionList/components';
import { RequisitionListForm } from '@/requisitionList/containers';
import { useText } from '@adobe-commerce/elsie/i18n';
import { ChevronDown, List } from '@adobe-commerce/elsie/icons';
import '@/requisitionList/containers/RequisitionListSelector/RequisitionListSelector.css';
import {
  useRequisitionLists,
  useRequisitionListAlert,
  useRequisitionListEnabled,
} from '@/requisitionList/hooks';
import { isMatchingRequisitionListItem } from '@/requisitionList/lib/requisition-list-item-comparator';
import { getRequisitionListsFromState } from '@/requisitionList/lib/state';

export interface RequisitionListSelectorProps
  extends HTMLAttributes<HTMLDivElement> {
  canCreate?: boolean;
  sku: string;
  selectedOptions?: string[];
  quantity?: number;
  matchBySKU?: boolean;
  beforeAddProdToReqList?: () => Promise<void> | void;
}

export const RequisitionListSelector: Container<
  RequisitionListSelectorProps
> = ({
  canCreate = true,
  sku,
  selectedOptions,
  quantity = 1,
  matchBySKU,
  beforeAddProdToReqList,
}: RequisitionListSelectorProps) => {
  const translations = useText({
    createTitle: `RequisitionList.RequisitionListForm.createTitle`,
    addToRequisitionList: `RequisitionList.RequisitionListForm.addToRequisitionList`,
    emptyList: `RequisitionList.RequisitionListWrapper.emptyList`,
    addToNewRequisitionList: `RequisitionList.RequisitionListSelector.addToNewRequisitionList`,
    addToSelected: `RequisitionList.RequisitionListSelector.addToSelected`,
  });
  const [isAdding, setIsAdding] = useState(false);
  const { lists } = useRequisitionLists();
  const { isEnabled } = useRequisitionListEnabled();

  // Keep lists in sync with event bus so active state updates in real time (e.g. when
  // another part of the page adds/removes this product from a list). Mirrors WishlistToggle.
  const [listsFromEvents, setListsFromEvents] = useState<RequisitionList[] | null>(
    null
  );

  useEffect(() => {
    const onRequisitionListsData = (payload: RequisitionList[] | null) => {
      if (payload) setListsFromEvents(payload);
    };
    const onRequisitionListData = (payload: RequisitionList | null) => {
      if (!payload) return;
      setListsFromEvents((prev) => {
        const currentLists = prev ?? getRequisitionListsFromState();
        const existingIndex = currentLists.findIndex(
          (list) => list.uid === payload!.uid
        );
        if (existingIndex >= 0) {
          return currentLists.map((list, i) =>
            i === existingIndex ? payload! : list
          );
        }
        return [...currentLists, payload];
      });
    };

    const unsubMulti = events.on('requisitionLists/data', onRequisitionListsData);
    const unsubSingle = events.on('requisitionList/data', onRequisitionListData);

    return () => {
      unsubMulti?.off();
      unsubSingle?.off();
    };
  }, []);

  const listsForActiveCheck = listsFromEvents ?? lists;

  const isInRequisitionList = useMemo(() => {
    if (!listsForActiveCheck?.length) return false;
    const productContext = { sku, selectedOptions };
    return listsForActiveCheck.some((list: RequisitionList) =>
      list.items?.some((item: Item) =>
        isMatchingRequisitionListItem(item, productContext, {
          matchBySkuOnly: matchBySKU,
        })
      )
    );
  }, [listsForActiveCheck, sku, selectedOptions, matchBySKU]);

  const { alert, setAlert, handleRequisitionListAlert } =
    useRequisitionListAlert();

  const [modal, setModal] = useState<{
    isOpen: boolean;
    isLoading: boolean;
  }>({
    isOpen: false,
    isLoading: false,
  });

  const handleOpenModal = useCallback(() => {
    setModal({ isOpen: true, isLoading: false });
  }, []);

  const handleCloseModal = useCallback(() => {
    setModal({ isOpen: false, isLoading: false });
    setIsAdding(false);
    setAlert(null);
  }, [setAlert]);

  const handleAddProdToReqList = useCallback(
    async (requisitionListUid: string) => {
      try {
        // Build the object dynamically, omitting selected_options if not present
        const itemToAdd = {
          sku,
          quantity,
          ...(selectedOptions && selectedOptions.length > 0
            ? { selected_options: selectedOptions }
            : {}),
        };

        await addProductsToRequisitionList(requisitionListUid, [itemToAdd]);
      } catch (error) {
        console.error('Error adding product to list:', error);
        throw error;
      }
    },
    [sku, quantity, selectedOptions]
  );

  const handleAddProductAndEmitAlert = useCallback(
    async (requisitionListUid: string) => {
      try {
        await handleAddProdToReqList(requisitionListUid);

        handleRequisitionListAlert({
          action: 'add',
          type: 'success',
          context: 'product',
          skus: [sku],
        });
      } catch {
        handleRequisitionListAlert({
          action: 'add',
          type: 'error',
          context: 'product',
          skus: [sku],
        });
      } finally {
        setTimeout(() => {
          handleCloseModal();
        }, 2000);
      }
    },
    [sku, handleAddProdToReqList, handleCloseModal, handleRequisitionListAlert]
  );

  const handleOpenModalWithValidation = useCallback(() => {
    if (!beforeAddProdToReqList) {
      handleOpenModal();
      return;
    }

    Promise.resolve(beforeAddProdToReqList())
      .then(() => {
        handleOpenModal();
      })
      .catch(() => {
        // Validation failed - don't open modal
      });
  }, [beforeAddProdToReqList, handleOpenModal]);

  const selectReqListSection =
    lists?.length > 0 ? (
      isAdding ? (
        <button
          type="button"
          aria-label="Select a requisition list"
          role="button"
          className="requisition-list-actions"
          data-testid="requisition-list-actions-button"
          onClick={() => setIsAdding(false)}
        >
          <span
            className="requisition-list-actions__title"
            data-testid="requisition-list-actions-button-text"
          >
            {translations.addToRequisitionList}
          </span>
          <Icon source={ChevronDown} size="32" />
        </button>
      ) : (
        <RequisitionListPicker
          confirmLabel={translations.addToSelected}
          onConfirm={handleAddProductAndEmitAlert}
        />
      )
    ) : (
      <EmptyList textContent={translations.emptyList} />
    );

  const createReqListSection = !isAdding ? (
    <RequisitionListActions
      onAddNew={() => {
        setIsAdding(true);
      }}
    />
  ) : (
    <Card variant="secondary">
      <RequisitionListForm
        mode="create"
        onSuccess={async (newList: RequisitionList) => {
          await handleAddProductAndEmitAlert(newList.uid);
        }}
        onError={() => {
          handleRequisitionListAlert({
            action: 'add',
            type: 'error',
            context: 'product',
            skus: [sku],
          });
        }}
        onCancel={() => {
          setIsAdding(false);
        }}
      />
    </Card>
  );

  const modalContent = (
    <>
      {alert && (
        <div className="requisition-list__alert-wrapper">
          <InLineAlert
            key={`requisition-list-selector__alert__${sku}`}
            id={`requisition-list-selector__alert__${sku}`}
            heading={alert.description}
            type={alert.type}
            variant="primary"
            className="requisition-list-selector__alert"
          />
        </div>
      )}
      {!alert && (
        <>
          {selectReqListSection}
          {canCreate && createReqListSection}
        </>
      )}
    </>
  );

  // Early return after all hooks have been called
  if (isEnabled === null || !isEnabled) {
    return null;
  }

  return (
    <div className="requisition-list-selector">
      <Button
        active={isInRequisitionList}
        activeIcon={<Icon source={List} />} // Change icon here for active state, (filled in icon for example)
        aria-label={translations.addToRequisitionList}
        className={isInRequisitionList ? 'requisition-list-selector--active' : undefined}
        data-testid="requisition-list-selector"
        size="medium"
        variant="tertiary"
        icon={<Icon source={List} />}
        onClick={handleOpenModalWithValidation}
      />
      {modal.isOpen && (
        <RequisitionListModal
          isOpen
          isLoading={modal.isLoading}
          title={translations.addToRequisitionList}
          modalContent={modalContent}
          handleModalOnClose={handleCloseModal}
        />
      )}
    </div>
  );
};
