import { useCallback, useState } from 'preact/compat';
import { useText } from '@adobe-commerce/elsie/i18n';
import { RequisitionListActionPayload } from 'adobe-commerce/event-bus';
import { RequisitionList } from '@/requisitionList/data/models/requisitionList';
import { moveItemsBetweenRequisitionLists } from '@/requisitionList/api/moveItemsBetweenRequisitionLists';
import { copyItemsBetweenRequisitionLists } from '@/requisitionList/api/copyItemsBetweenRequisitionLists';

export interface UseRequisitionListTransferOptions {
  sourceListUid: string;
  selectedItems: Set<string>;
  currentPageSize: number;
  currentPage: number;
  enrichConfigurableProductsInList: (
    list: RequisitionList
  ) => Promise<RequisitionList>;
  fetchAndMergeProducts: (
    list: RequisitionList
  ) => Promise<RequisitionList>;
  setCurrentRequisitionList: (list: RequisitionList) => void;
  setSelectedItems: (items: Set<string>) => void;
  handleRequisitionListAlert: (
    payload: RequisitionListActionPayload
  ) => void;
}

export function useRequisitionListTransfer({
  sourceListUid,
  selectedItems,
  currentPageSize,
  currentPage,
  enrichConfigurableProductsInList,
  fetchAndMergeProducts,
  setCurrentRequisitionList,
  setSelectedItems,
  handleRequisitionListAlert,
}: UseRequisitionListTransferOptions) {
  const [showMoveToListModal, setShowMoveToListModal] = useState(false);
  const [movingToList, setMovingToList] = useState(false);
  const [showCopyToListModal, setShowCopyToListModal] = useState(false);
  const [copyingToList, setCopyingToList] = useState(false);

  const translations = useText({
    successMoveToList: `RequisitionList.RequisitionListAlert.successMoveToList`,
    successCopyToList: `RequisitionList.RequisitionListAlert.successCopyToList`,
  });

  const handleMoveToList = useCallback(
    async (destinationListUid: string) => {
      if (selectedItems.size === 0) return;

      setMovingToList(true);

      try {
        const result = await moveItemsBetweenRequisitionLists(
          sourceListUid,
          destinationListUid,
          Array.from(selectedItems),
          currentPageSize,
          currentPage
        );

        if (result?.sourceList) {
          const enrichedWithConfigurable =
            await enrichConfigurableProductsInList(result.sourceList);
          const enrichedList =
            await fetchAndMergeProducts(enrichedWithConfigurable);
          setCurrentRequisitionList(enrichedList);
          setSelectedItems(new Set());

          const listName = result.destinationList?.name || '';
          handleRequisitionListAlert({
            action: 'moveToList',
            type: 'success',
            context: 'product',
            message: [
              translations.successMoveToList.replace('{listName}', listName),
            ],
          });
        } else {
          handleRequisitionListAlert({
            action: 'moveToList',
            type: 'error',
            context: 'product',
          });
        }
      } catch {
        handleRequisitionListAlert({
          action: 'moveToList',
          type: 'error',
          context: 'product',
        });
      } finally {
        setMovingToList(false);
        setShowMoveToListModal(false);
      }
    },
    [
      selectedItems,
      sourceListUid,
      currentPageSize,
      currentPage,
      enrichConfigurableProductsInList,
      fetchAndMergeProducts,
      setCurrentRequisitionList,
      setSelectedItems,
      handleRequisitionListAlert,
      translations.successMoveToList,
    ]
  );

  const handleCopyToList = useCallback(
    async (destinationListUid: string) => {
      if (selectedItems.size === 0) return;

      setCopyingToList(true);

      try {
        const result = await copyItemsBetweenRequisitionLists(
          sourceListUid,
          destinationListUid,
          Array.from(selectedItems)
        );

        if (result?.destinationList) {
          setSelectedItems(new Set());

          const listName = result.destinationList.name || '';
          handleRequisitionListAlert({
            action: 'copyToList',
            type: 'success',
            context: 'product',
            message: [
              translations.successCopyToList.replace('{listName}', listName),
            ],
          });
        } else {
          handleRequisitionListAlert({
            action: 'copyToList',
            type: 'error',
            context: 'product',
          });
        }
      } catch {
        handleRequisitionListAlert({
          action: 'copyToList',
          type: 'error',
          context: 'product',
        });
      } finally {
        setCopyingToList(false);
        setShowCopyToListModal(false);
      }
    },
    [
      selectedItems,
      sourceListUid,
      setSelectedItems,
      handleRequisitionListAlert,
      translations.successCopyToList,
    ]
  );

  return {
    showMoveToListModal,
    setShowMoveToListModal,
    movingToList,
    showCopyToListModal,
    setShowCopyToListModal,
    copyingToList,
    handleMoveToList,
    handleCopyToList,
  };
}
