import { FunctionComponent } from 'preact';
import { HTMLAttributes } from 'preact/compat';
import '@/requisitionList/components/RequisitionListHeader/RequisitionListHeader.css';

export interface RequisitionListHeaderProps
  extends HTMLAttributes<HTMLDivElement> {
  name: string;
  description?: string;
  backLink?: {
    url: string;
    label: string;
    onClick?: (e: Event) => void;
  };
  actions?: {
    onRename?: () => void;
    onDelete?: () => void;
    onShare?: () => void;
    renameLabel?: string;
    deleteLabel?: string;
    shareLabel?: string;
    shareDisabled?: boolean;
    shareDisabledReason?: string;
  };
}

export const RequisitionListHeader: FunctionComponent<
  RequisitionListHeaderProps
> = ({ name, description, backLink, actions, className, ...props }) => {
  return (
    <div {...props} className={`requisition-list-header ${className || ''}`}>
      {/* Back Link */}
      {backLink && (
        <div className="requisition-list-header__back">
          <a
            href={backLink.url}
            className="requisition-list-header__back-link"
            onClick={backLink.onClick}
          >
            <span className="requisition-list-header__back-arrow">&lt;</span>
            {backLink.label}
          </a>
        </div>
      )}

      {/* Title and Actions Row */}
      <div className="requisition-list-header__main">
        <div className="requisition-list-header__title-section">
          <h1 className="requisition-list-header__title">{name}</h1>
          {description && (
            <p className="requisition-list-header__description">
              {description}
            </p>
          )}
        </div>

        {/* Action Links */}
        {actions &&
          (actions.onRename ||
            actions.onDelete ||
            actions.onShare ||
            actions.shareDisabled) && (
            <div className="requisition-list-header__actions">
              {(actions.onShare || actions.shareDisabled) && (
                <a
                  href="#"
                  onClick={(e) => {
                    e.preventDefault();
                    if (actions.shareDisabled) {
                      return;
                    }
                    actions.onShare?.();
                  }}
                  className={`requisition-list-header__action-link ${
                    actions.shareDisabled
                      ? 'requisition-list-header__action-link--disabled'
                      : ''
                  }`}
                  data-testid="share-list-btn"
                  aria-disabled={actions.shareDisabled ? 'true' : 'false'}
                  aria-label={
                    actions.shareDisabled && actions.shareDisabledReason
                      ? `${actions.shareLabel} – ${actions.shareDisabledReason}`
                      : undefined
                  }
                  data-disabled-reason={
                    actions.shareDisabled
                      ? actions.shareDisabledReason
                      : undefined
                  }
                >
                  {actions.shareLabel}
                </a>
              )}
              {actions.onRename && (
                <a
                  href="#"
                  onClick={(e) => {
                    e.preventDefault();
                    actions.onRename?.();
                  }}
                  className="requisition-list-header__action-link"
                  data-testid="rename-list-btn"
                >
                  {actions.renameLabel}
                </a>
              )}
              {actions.onDelete && (
                <a
                  href="#"
                  onClick={(e) => {
                    e.preventDefault();
                    actions.onDelete?.();
                  }}
                  className="requisition-list-header__action-link"
                  data-testid="delete-list-btn"
                >
                  {actions.deleteLabel}
                </a>
              )}
            </div>
          )}
      </div>
    </div>
  );
};
