import { Item } from '@/requisitionList/data/models/item';

export interface ProductLike {
  sku: string;
  selectedOptions?: string[];
}

/**
 * Compares a requisition list item to the current product context (sku + selected options).
 * Used to determine if the product is already in a requisition list for active state.
 * Default: only SKU is compared. Option UIDs are compared only when options.matchBySkuOnly is false.
 */
export function isMatchingRequisitionListItem(
  requisitionListItem: Item,
  product: ProductLike,
  options?: { matchBySkuOnly?: boolean }
): boolean {
  const itemSku = requisitionListItem.sku ?? requisitionListItem.product?.sku;
  if (!itemSku || itemSku !== product.sku) {
    return false;
  }

  // Default: match by SKU only. Only compare option UIDs when matchBySkuOnly is explicitly false.
  if (options?.matchBySkuOnly !== false) return true;

  // Extract without sorting first to allow an early exit
  const itemOptionUids = (requisitionListItem.configurable_options ?? [])
    .map((opt) => opt.value_uid)
    .filter((uid): uid is string => !!uid);

  const productOptionUids = (product.selectedOptions ?? [])
    .filter((uid): uid is string => !!uid);

  // Early return if they don't have the same number of options
  if (itemOptionUids.length !== productOptionUids.length) {
    return false;
  }

  // Sort only after we know lengths match
  itemOptionUids.sort();
  productOptionUids.sort();

  // Compare element by element
  return itemOptionUids.every((uid, index) => uid === productOptionUids[index]);
}
