import { useEffect, useState } from 'preact/compat';
import { state } from '@/requisitionList/lib/state';
import { events } from '@adobe-commerce/event-bus';

function isRequisitionListEnabled(): boolean {
  const config = state.config;
  if (!config) return false;
  return (
    config.is_requisition_list_active === '1' &&
    config.company_enabled === true
  );
}

export const useRequisitionListEnabled = () => {
  const [isEnabled, setIsEnabled] = useState<boolean>(isRequisitionListEnabled);

  useEffect(() => {
    // Listen for requisition list initialization via event bus
    const configListener = events.on('requisitionList/initialized', () => {
      // Only set false when config explicitly disables; if config is missing
      // (e.g. re-init race), preserve current value so the button doesn't disappear
      const enabled = isRequisitionListEnabled();
      setIsEnabled((prev) => (state.config != null ? enabled : prev));
    });

    return () => configListener?.off();
  }, []);

  return { isEnabled };
};
