import { FunctionComponent } from 'preact';
import {
  Button,
  Header,
  InLineAlert,
  ProgressSpinner,
  Table,
} from '@adobe-commerce/elsie/components';
import { SharedRequisitionListResult } from '@/requisitionList/api/getSharedRequisitionList';
import { Item } from '@/requisitionList/data/models/item';
import '@/requisitionList/components/SharedRequisitionList/SharedRequisitionList.css';

export type SharedRequisitionListStatus =
  | 'preview_loading'
  | 'preview_loaded'
  | 'preview_error'
  | 'importing'
  | 'import_success'
  | 'import_error';

export interface SharedRequisitionListProps {
  status: SharedRequisitionListStatus;
  previewData: SharedRequisitionListResult | null;
  errorMessage: string;
  onImport: () => void;
  translations: {
    loading: string;
    previewTitle: string;
    senderLabel: string;
    listNameLabel: string;
    descriptionLabel: string;
    itemsCountLabel: string;
    importButton: string;
    importingButton: string;
    successImport: string;
    skuHeader: string;
    qtyHeader: string;
    optionsHeader: string;
  };
}

const getItemOptions = (item: Item): string => {
  if (item.configurable_options?.length) {
    return item.configurable_options
      .map((opt) => `${opt.option_label}: ${opt.value_label}`)
      .join(', ');
  }
  if (item.bundle_options?.length) {
    return item.bundle_options.map((opt) => opt.label).join(', ');
  }
  return '';
};

export const SharedRequisitionList: FunctionComponent<
  SharedRequisitionListProps
> = ({ status, previewData, errorMessage, onImport, translations }) => {
  if (status === 'preview_loading') {
    return (
      <div className="shared-requisition-list__loading">
        <ProgressSpinner />
        <span>{translations.loading}</span>
      </div>
    );
  }

  if (status === 'preview_error') {
    return (
      <div className="shared-requisition-list__container">
        <InLineAlert heading={errorMessage} type="error" variant="primary" />
      </div>
    );
  }

  if (!previewData) {
    return null;
  }

  const listName = previewData.requisitionList.name;
  const items = previewData.requisitionList.items ?? [];
  const isImporting = status === 'importing';
  const isImported = status === 'import_success';

  const columns = [
    { label: translations.skuHeader, key: 'sku' },
    { label: translations.qtyHeader, key: 'qty' },
    { label: translations.optionsHeader, key: 'options' },
  ];

  const rowData = items.map((item) => ({
    sku: item.sku,
    qty: item.quantity,
    options: getItemOptions(item),
  }));

  return (
    <div className="shared-requisition-list__preview">
      <Header
        title={translations.previewTitle}
        aria-label={translations.previewTitle}
      />

      {status === 'import_success' && (
        <div className="shared-requisition-list__alert-wrapper">
          <InLineAlert
            heading={translations.successImport.replace('{listName}', listName)}
            type="success"
            variant="primary"
          />
        </div>
      )}

      {status === 'import_error' && (
        <div className="shared-requisition-list__alert-wrapper">
          <InLineAlert heading={errorMessage} type="error" variant="primary" />
        </div>
      )}

      <div className="shared-requisition-list__preview-details">
        <div className="shared-requisition-list__preview-row">
          <span className="shared-requisition-list__preview-label">
            {translations.senderLabel}
          </span>
          <span className="shared-requisition-list__preview-value">
            {previewData.senderName}
          </span>
        </div>
        <div className="shared-requisition-list__preview-row">
          <span className="shared-requisition-list__preview-label">
            {translations.listNameLabel}
          </span>
          <span className="shared-requisition-list__preview-value">
            {listName}
          </span>
        </div>
        {previewData.requisitionList.description && (
          <div className="shared-requisition-list__preview-row">
            <span className="shared-requisition-list__preview-label">
              {translations.descriptionLabel}
            </span>
            <span className="shared-requisition-list__preview-value">
              {previewData.requisitionList.description}
            </span>
          </div>
        )}
      </div>

      {items.length > 0 && (
        <div className="shared-requisition-list__table-wrapper">
          <Table
            columns={columns}
            rowData={rowData}
            data-testid="shared-list-items-table"
          />
        </div>
      )}

      <div className="shared-requisition-list__actions">
        <Button
          type="button"
          variant="primary"
          onClick={onImport}
          disabled={isImporting || isImported}
          data-testid="import-shared-list-btn"
        >
          {isImporting
            ? translations.importingButton
            : translations.importButton}
        </Button>
      </div>
    </div>
  );
};
