import { useCallback, useEffect, useRef, useState } from 'preact/compat';
import { Container } from '@adobe-commerce/elsie/lib';
import { useText } from '@adobe-commerce/elsie/i18n';
import { events } from '@adobe-commerce/event-bus';
import {
  getSharedRequisitionList,
  SharedRequisitionListResult,
} from '@/requisitionList/api/getSharedRequisitionList';
import { importSharedRequisitionList } from '@/requisitionList/api/importSharedRequisitionList';
import {
  SharedRequisitionList as SharedRequisitionListView,
  SharedRequisitionListStatus,
} from '@/requisitionList/components/SharedRequisitionList';

export interface SharedRequisitionListProps {
  /**
   * The share token from the URL (e.g. from ?requisition_id=<token>).
   */
  token: string;
  /**
   * Called with the imported list UID and list name on a successful import.
   * The integration should navigate to the requisition list detail page.
   *
   * Note: this callback is captured at mount time. Pass a stable reference
   * (e.g. a module-level function or a `useCallback` with no deps) so that
   * the closure always holds the correct value.
   */
  routeRequisitionList?: (uid: string, listName: string) => string | void;
}

export const SharedRequisitionList: Container<SharedRequisitionListProps> = ({
  token,
  routeRequisitionList,
}: SharedRequisitionListProps) => {
  const [status, setStatus] = useState<SharedRequisitionListStatus>('preview_loading');
  const [previewData, setPreviewData] =
    useState<SharedRequisitionListResult | null>(null);
  const [errorMessage, setErrorMessage] = useState('');
  const isMountedRef = useRef(true);

  const translations = useText({
    loading: 'RequisitionList.SharedRequisitionList.loading',
    previewTitle: 'RequisitionList.SharedRequisitionList.previewTitle',
    senderLabel: 'RequisitionList.SharedRequisitionList.senderLabel',
    listNameLabel: 'RequisitionList.SharedRequisitionList.listNameLabel',
    descriptionLabel: 'RequisitionList.SharedRequisitionList.descriptionLabel',
    itemsCountLabel: 'RequisitionList.SharedRequisitionList.itemsCountLabel',
    importButton: 'RequisitionList.SharedRequisitionList.importButton',
    importingButton: 'RequisitionList.SharedRequisitionList.importingButton',
    errorPreview: 'RequisitionList.SharedRequisitionList.errorPreview',
    successImport: 'RequisitionList.RequisitionListAlert.successImport',
    errorImport: 'RequisitionList.RequisitionListAlert.errorImport',
    skuHeader: 'RequisitionList.SharedRequisitionList.skuHeader',
    qtyHeader: 'RequisitionList.SharedRequisitionList.qtyHeader',
    optionsHeader: 'RequisitionList.SharedRequisitionList.optionsHeader',
  });

  useEffect(() => {
    return () => {
      isMountedRef.current = false;
    };
  }, []);

  useEffect(() => {
    getSharedRequisitionList(token)
      .then((result) => {
        if (!isMountedRef.current) return;

        if (!result) {
          setErrorMessage('');
          setStatus('preview_error');
          return;
        }

        setPreviewData(result);
        setStatus('preview_loaded');
      })
      .catch((err: unknown) => {
        if (!isMountedRef.current) return;
        setErrorMessage(err instanceof Error && err.message ? err.message : '');
        setStatus('preview_error');
      });
  }, [token]);

  const handleImport = useCallback(() => {
    setStatus('importing');
    setErrorMessage('');

    importSharedRequisitionList(token)
      .then(({ requisitionList, userErrors }) => {
        if (!isMountedRef.current) return;

        if (userErrors.length > 0) {
          setErrorMessage(userErrors[0].message);
          setStatus('import_error');
          return;
        }

        const name = requisitionList?.name ?? '';
        const uid = requisitionList?.uid ?? '';

        events.emit('requisitionList/alert', {
          action: 'import',
          type: 'success',
          context: 'requisitionList',
          listName: name,
        });

        if (routeRequisitionList) {
          routeRequisitionList(uid, name);
          return;
        }

        setStatus('import_success');
      })
      .catch((err: unknown) => {
        if (!isMountedRef.current) return;
        setErrorMessage(err instanceof Error && err.message ? err.message : '');
        setStatus('import_error');
      });
  }, [token, routeRequisitionList]);

  // Resolve the translation fallback at render time so effects don't need
  // translations in their dependency arrays.
  const resolvedErrorMessage =
    errorMessage ||
    (status === 'import_error' ? translations.errorImport : translations.errorPreview);

  return (
    <SharedRequisitionListView
      status={status}
      previewData={previewData}
      errorMessage={resolvedErrorMessage}
      onImport={handleImport}
      translations={translations}
    />
  );
};
