import { FunctionComponent } from 'preact';
import {
  Button,
  Divider,
  Field,
  Input,
  ProgressSpinner,
  MultiSelect,
} from '@adobe-commerce/elsie/components';
import { useText } from '@adobe-commerce/elsie/i18n';
import '@/requisitionList/components/ShareRequisitionListContent/ShareRequisitionListContent.css';

export interface ShareRequisitionListContentProps {
  loadingUsers: boolean;
  usersErrorMessage: string | null;
  loadingLink: boolean;
  selectedUserValues: string[];
  multiSelectOptions: Array<{ label: string; value: string }>;
  shareLink: string | null;
  linkErrorMessage: string | null;
  linkCopied: boolean;
  isSubmitting: boolean;
  canSubmit: boolean;
  onSubmitClick: () => void;
  onCopyLinkClick: () => void;
  onSelectedUsersChange: (values: Array<string | number>) => void;
  onUsersFieldInteract: () => void;
  selectionError: string | null;
  submitErrorMessage: string | null;
  isShareSuccess: boolean;
  sharedRecipientEmails: string[];
}

export const ShareRequisitionListContent: FunctionComponent<
  ShareRequisitionListContentProps
> = ({
  loadingUsers,
  usersErrorMessage,
  loadingLink,
  selectedUserValues,
  multiSelectOptions,
  shareLink,
  linkErrorMessage,
  linkCopied,
  isSubmitting,
  canSubmit,
  onSubmitClick,
  onCopyLinkClick,
  onSelectedUsersChange,
  onUsersFieldInteract,
  selectionError,
  submitErrorMessage,
  isShareSuccess,
  sharedRecipientEmails,
}) => {
  const translations = useText({
    emailInstruction:
      'RequisitionList.ShareRequisitionListContent.emailInstruction',
    emailLabel: 'RequisitionList.ShareRequisitionListContent.emailLabel',
    emailPlaceholder:
      'RequisitionList.ShareRequisitionListContent.emailPlaceholder',
    submitLabel: 'RequisitionList.ShareRequisitionListContent.submitLabel',
    linkInstruction:
      'RequisitionList.ShareRequisitionListContent.linkInstruction',
    copyLink: 'RequisitionList.ShareRequisitionListContent.copyLink',
    linkCopied: 'RequisitionList.ShareRequisitionListContent.linkCopied',
    loadingUsers: 'RequisitionList.ShareRequisitionListContent.loadingUsers',
    loadingLink: 'RequisitionList.ShareRequisitionListContent.loadingLink',
    noUsersAvailable:
      'RequisitionList.ShareRequisitionListContent.noUsersAvailable',
    maxRecipientsValidation:
      'RequisitionList.ShareRequisitionListContent.maxRecipientsValidation',
    shareSuccessMessage:
      'RequisitionList.ShareRequisitionListContent.shareSuccessMessage',
  });
  return (
    <div className="share-requisition-list-content">
      {/* Email section */}
      {isShareSuccess ? (
        <div className="share-requisition-list-content__success">
          <p className="share-requisition-list-content__instruction">
            {translations.shareSuccessMessage}
          </p>
          <div className="share-requisition-list-content__recipient-list">
            {sharedRecipientEmails.map((email) => (
              <p
                key={email}
                className="share-requisition-list-content__recipient"
              >
                {email}
              </p>
            ))}
          </div>
        </div>
      ) : (
        <>
          <p className="share-requisition-list-content__instruction">
            {translations.emailInstruction}
          </p>

          <div className="share-requisition-list-content__field">
            {loadingUsers ? (
              <div className="share-requisition-list-content__loading">
                <ProgressSpinner size="small" stroke="3" />
                <span>{translations.loadingUsers}</span>
              </div>
            ) : usersErrorMessage ? (
              <p className="dropin-field__hint dropin-field__hint--medium dropin-field__hint--error">
                {usersErrorMessage}
              </p>
            ) : (
              <Field
                label={translations.emailLabel}
                error={selectionError ?? undefined}
                disabled={isSubmitting}
                onMouseDown={onUsersFieldInteract}
                onKeyDown={onUsersFieldInteract}
              >
                <MultiSelect
                  options={multiSelectOptions}
                  value={selectedUserValues}
                  onChange={onSelectedUsersChange}
                  placeholder={translations.emailPlaceholder}
                  noResultsText={translations.noUsersAvailable}
                  disabled={isSubmitting}
                  error={!!selectionError}
                  className="share-requisition-list-content__multi-select"
                />
              </Field>
            )}
          </div>

          <div className="share-requisition-list-content__actions">
            <Button
              variant="primary"
              onClick={onSubmitClick}
              disabled={!canSubmit}
              type="button"
              data-testid="share-submit-btn"
            >
              {translations.submitLabel}
            </Button>
          </div>
          {submitErrorMessage && (
            <p className="dropin-field__hint dropin-field__hint--medium dropin-field__hint--error">
              {submitErrorMessage}
            </p>
          )}
        </>
      )}

      {/* Link section */}
      <Divider
        variant={'secondary'}
        className="share-requisition-list-content__divider-secondary"
      />

      <p className="share-requisition-list-content__instruction">
        {translations.linkInstruction}
      </p>

      {loadingLink ? (
        <div className="share-requisition-list-content__loading">
          <ProgressSpinner size="small" stroke="3" />
          <span>{translations.loadingLink}</span>
        </div>
      ) : shareLink ? (
        <>
          <div className="share-requisition-list-content__link-row">
            <Input
              readOnly
              value={shareLink}
              data-testid="share-link-field"
            />
          </div>

          <div className="share-requisition-list-content__actions">
            <Button
              variant="secondary"
              onClick={onCopyLinkClick}
              type="button"
              data-testid="copy-link-btn"
            >
              {linkCopied ? translations.linkCopied : translations.copyLink}
            </Button>
          </div>
        </>
      ) : linkErrorMessage ? (
        <p className="dropin-field__hint dropin-field__hint--medium dropin-field__hint--error">
          {linkErrorMessage}
        </p>
      ) : null}
    </div>
  );
};
