import {
  HTMLAttributes,
  useState,
  useCallback,
  useEffect,
} from 'preact/compat';
import { Container } from '@adobe-commerce/elsie/lib';
import { useText } from '@adobe-commerce/elsie/i18n';
import {
  addRequisitionListItemsToCart,
  AddToCartError,
} from '@/requisitionList/api/addRequisitionListItemsToCart';
import { deleteRequisitionListItems } from '@/requisitionList/api/deleteRequisitionListItems';
import { updateRequisitionListItems } from '@/requisitionList/api/updateRequisitionListItems';
import { getRequisitionList } from '@/requisitionList/api/getRequisitionList';
import {
  Pagination,
  InLineAlert,
  ProgressSpinner,
} from '@adobe-commerce/elsie/components';
import { Item, Product } from '@/requisitionList/data/models/item';
import { RequisitionList } from '@/requisitionList/data/models/requisitionList';
import { events } from '@adobe-commerce/event-bus';
import {
  PageSizePicker,
  EmptyList,
  NotFound,
  RequisitionListModal,
  PaginationItemsCounter,
  RequisitionListPicker,
} from '@/requisitionList/components';
import { ProductListTable } from '@/requisitionList/components/ProductListTable/ProductListTable';
import { BatchActions } from '@/requisitionList/components/BatchActions/BatchActions';
import { RequisitionListHeader } from '@/requisitionList/containers/RequisitionListHeader';
import { useRequisitionListSelectedItems } from '@/requisitionList/hooks/useRequisitionListSelectedItems';
import { useRequisitionListAlert } from '@/requisitionList/hooks/useRequisitionListAlert';
import { useRequisitionListEnabled } from '@/requisitionList/hooks/useRequisitionListEnabled';
import { useRequisitionListTransfer } from '@/requisitionList/hooks/useRequisitionListTransfer';
import { isValidBase64Uid } from '@/requisitionList/lib/validate-uid';
import { DEFAULT_PAGE_SIZE } from '@/requisitionList/lib/constants';
import '@/requisitionList/containers/RequisitionListView/RequisitionListView.css';

export interface RequisitionListViewProps
  extends HTMLAttributes<HTMLDivElement> {
  /**
   * The UID of the requisition list to display.
   * The UID must be a base64-encoded string.
   * If an invalid UID is provided, the component will render the NotFound state.
   * The component will fetch the requisition list data internally.
   */
  requisitionListUid: string;
  /**
   * When true, skips automatic product data fetching on component mount.
   * Used in tests to prevent API calls.
   */
  skipProductLoading?: boolean;
  /**
   * Number of items per page for pagination.
   * Defaults to DEFAULT_PAGE_SIZE.
   */
  pageSize?: number;
  selectedItems: Set<string>;
  /**
   * Function that returns the URL to the requisition list grid view or performs navigation
   */
  routeRequisitionListGrid?: () => string | void;
  /**
   * Fallback URL to redirect when requisition lists are not enabled.
   * Defaults to '/customer/account'
   */
  fallbackRoute?: string;
  getProductData: (skus: string[]) => Promise<Product[] | null>;
  enrichConfigurableProducts: (items: Item[]) => Promise<Item[]>;
  currentCustomerEmail?: string;
  routeSharedRequisitionList?: (relativeUrl: string) => string;
}

export const RequisitionListView: Container<RequisitionListViewProps> = ({
  requisitionListUid,
  skipProductLoading = false,
  pageSize = DEFAULT_PAGE_SIZE,
  routeRequisitionListGrid,
  fallbackRoute = '/customer/account',
  getProductData,
  enrichConfigurableProducts,
  currentCustomerEmail,
  routeSharedRequisitionList,
}: RequisitionListViewProps) => {
  const [loadingProducts, setLoadingProducts] = useState<boolean>(false);
  const [deletingItemId, setDeletingItemId] = useState<string | null>(null);
  const [addingToCartItemId, setAddingToCartItemId] = useState<
    string[] | undefined
  >(null);
  const [bulkAddingToCart, setBulkAddingToCart] = useState<boolean>(false);
  const [updatingQuantityItemId, setUpdatingQuantityItemId] = useState<
    string | null
  >(null);
  const [loadingPage, setLoadingPage] = useState<boolean>(false);
  const [currentPageSize, setCurrentPageSize] = useState<number>(pageSize);
  const [initializing, setInitializing] = useState<boolean>(true);
  const [showDeleteModal, setShowDeleteModal] = useState<boolean>(false);
  const [itemsToDelete, setItemsToDelete] = useState<string[]>([]);
  const {
    currentRequisitionList,
    setCurrentRequisitionList,
    selectedItems,
    setSelectedItems,
    handleItemSelection,
    handleSelectAll,
    handleSelectNone,
  } = useRequisitionListSelectedItems();

  const translations = useText({
    emptyRequisitionList: `RequisitionList.RequisitionListView.emptyRequisitionList`,
    errorLoadingProducts: `RequisitionList.RequisitionListView.errorLoadingProducts`,
    errorLoadPage: `RequisitionList.RequisitionListView.errorLoadPage`,
    notFoundTitle: `RequisitionList.RequisitionListView.notFoundTitle`,
    notFoundMessage: `RequisitionList.RequisitionListView.notFoundMessage`,
    notFoundActionLabel: `RequisitionList.RequisitionListView.notFoundActionLabel`,
    notEnabledTitle: `RequisitionList.RequisitionListsNotEnabled.title`,
    notEnabledMessage: `RequisitionList.RequisitionListsNotEnabled.message`,
    partialMoveSuccess: `RequisitionList.RequisitionListAlert.partialMoveSuccess`,
    notEnabledActionLabel: `RequisitionList.RequisitionListsNotEnabled.actionLabel`,
    show: `RequisitionList.PageSizePicker.show`,
    deleteItemsTitle: `RequisitionList.RequisitionListView.deleteItemsTitle`,
    deleteItemsMessage: `RequisitionList.RequisitionListView.deleteItemsMessage`,
    confirmAction: `RequisitionList.RequisitionListView.confirmAction`,
    cancelAction: `RequisitionList.RequisitionListView.cancelAction`,
    moveToListTitle: `RequisitionList.RequisitionListView.moveToListTitle`,
    moveToListConfirm: `RequisitionList.RequisitionListView.moveToListConfirm`,
    copyToListTitle: `RequisitionList.RequisitionListView.copyToListTitle`,
    copyToListConfirm: `RequisitionList.RequisitionListView.copyToListConfirm`,
  });

  const { alert, setAlert, handleRequisitionListAlert } =
    useRequisitionListAlert();

  const { isEnabled } = useRequisitionListEnabled();

  useEffect(() => {
    const requisitionListEvent = events.on(
      'requisitionList/data',
      (payload: RequisitionList) => {
        // Only update from events if it matches our current UID
        if (payload?.uid === requisitionListUid) {
          setCurrentRequisitionList(payload);
          setSelectedItems(new Set());
        }
      }
    );
    // Keep event listener for cross-component alert communication
    const alertEvent = events.on(
      'requisitionList/alert',
      handleRequisitionListAlert
    );
    return () => {
      requisitionListEvent?.off();
      alertEvent?.off();
    };
  }, [
    handleRequisitionListAlert,
    requisitionListUid,
    setCurrentRequisitionList,
    setSelectedItems,
  ]);

  // Sync pageSize prop changes to local state
  useEffect(() => {
    setCurrentPageSize(pageSize);
  }, [pageSize]);

  // Function to enrich configurable products
  const enrichConfigurableProductsInList = useCallback(
    async (baseRequisitionList: RequisitionList): Promise<RequisitionList> => {
      if (!baseRequisitionList.items?.length) {
        return baseRequisitionList;
      }
      if (typeof enrichConfigurableProducts !== 'function') {
        return baseRequisitionList;
      }

      const enrichedItems = await enrichConfigurableProducts(
        baseRequisitionList.items
      );
      return {
        ...baseRequisitionList,
        items: enrichedItems,
      };
    },
    [enrichConfigurableProducts]
  );

  // Function to fetch and merge product data
  const fetchAndMergeProducts = useCallback(
    async (baseRequisitionList: RequisitionList) => {
      // Extract SKUs from requisition list items
      const productSkus =
        baseRequisitionList.items?.map((item: Item) => item.sku) || [];

      if (productSkus.length === 0) {
        return baseRequisitionList;
      }

      setLoadingProducts(true);

      try {
        const fetchedProducts = await getProductData(productSkus);
        if (fetchedProducts) {
          // Create a map of SKU to Product for easy lookup
          const productMap = new Map<string, Product>();
          fetchedProducts.forEach((product: Product) => {
            productMap.set(product.sku, product);
          });

          // Update requisition list items with fetched product data
          return {
            ...baseRequisitionList,
            items: baseRequisitionList.items?.map((item: Item) => {
              const fetchedProduct = productMap.get(item.sku);
              return {
                ...item,
                product: fetchedProduct || item.product, // Use fetched product or keep existing
                stock_status: (item.stock_status ||
                  fetchedProduct?.stock_status ||
                  'IN_STOCK') as 'IN_STOCK' | 'OUT_OF_STOCK',
                only_x_left_in_stock:
                  item.only_x_left_in_stock ??
                  fetchedProduct?.only_x_left_in_stock ??
                  null,
              };
            }),
          };
        }
        console.warn('No products found');
        return baseRequisitionList;
      } catch (error) {
        console.warn(
          error instanceof Error
            ? error.message
            : translations.errorLoadingProducts
        );
        return baseRequisitionList;
      } finally {
        setLoadingProducts(false);
      }
    },
    [getProductData, translations.errorLoadingProducts]
  );

  const {
    showMoveToListModal,
    setShowMoveToListModal,
    movingToList,
    showCopyToListModal,
    setShowCopyToListModal,
    copyingToList,
    handleMoveToList,
    handleCopyToList,
  } = useRequisitionListTransfer({
    sourceListUid: currentRequisitionList?.uid,
    selectedItems,
    currentPageSize,
    currentPage: currentRequisitionList?.page_info?.current_page || 1,
    enrichConfigurableProductsInList,
    fetchAndMergeProducts,
    setCurrentRequisitionList,
    setSelectedItems,
    handleRequisitionListAlert,
  });

  // Initialize requisition list from UID
  // Only triggers initial load when UID changes. Page size changes trigger pagination, not re-initialization.
  useEffect(() => {
    if (!requisitionListUid) {
      setInitializing(false);
      return;
    }

    // Only initialize if we don't have a list or if the UID changed
    if (
      currentRequisitionList &&
      currentRequisitionList.uid === requisitionListUid
    ) {
      // Same list already loaded, don't re-initialize
      return;
    }

    setInitializing(true);

    const initializeFromUid = async () => {
      try {
        const fetchedList = await getRequisitionList(
          requisitionListUid,
          1,
          pageSize,
          enrichConfigurableProducts
        );

        if (fetchedList) {
          // List already enriched via getRequisitionList(enrichConfigurableProducts)
          if (!skipProductLoading) {
            const enrichedList = await fetchAndMergeProducts(fetchedList);
            setCurrentRequisitionList(enrichedList);
          } else {
            setCurrentRequisitionList(fetchedList);
          }
        }
      } catch (error) {
        console.error('Failed to initialize requisition list from UID:', error);
      } finally {
        setInitializing(false);
      }
    };

    initializeFromUid();
  }, [
    requisitionListUid,
    pageSize,
    skipProductLoading,
    enrichConfigurableProducts,
    fetchAndMergeProducts,
    setCurrentRequisitionList,
    currentRequisitionList,
  ]);

  const handleAddItemsToCart = useCallback(
    async (itemUids: string[] | undefined) => {
      if (itemUids && itemUids.length === 1) {
        setBulkAddingToCart(false);
        setAddingToCartItemId(itemUids);
      } else {
        setBulkAddingToCart(true);
        setAddingToCartItemId(null);
      }

      try {
        const errors = await addRequisitionListItemsToCart(
          currentRequisitionList.uid,
          itemUids
        );

        const totalItems = itemUids?.length || 0;
        const errorCount = errors?.length || 0;
        const successCount = totalItems - errorCount;

        // Check for partial success: some items succeeded and some failed
        if (errors && errors.length > 0 && successCount > 0) {
          const alertPayload = {
            action: 'move',
            type: 'error',
            context: 'product',
            message: [
              translations.partialMoveSuccess
                .replace('{successCount}', String(successCount))
                .replace('{failedCount}', String(errorCount)),
            ],
          };
          handleRequisitionListAlert(alertPayload);
          events.emit('requisitionList/alert', alertPayload);
        } else if (errors && errors.length > 0) {
          // All items failed
          const alertPayload = {
            action: 'move',
            type: 'error',
            context: 'product',
            message: errors.map((e: AddToCartError) => e.message),
          };
          handleRequisitionListAlert(alertPayload);
          events.emit('requisitionList/alert', alertPayload);
        } else {
          // All items succeeded
          const alertPayload = {
            action: 'move',
            type: 'success',
            context: 'product',
          };
          handleRequisitionListAlert(alertPayload);
          events.emit('requisitionList/alert', alertPayload);
        }
      } catch (error) {
        const alertPayload = {
          action: 'move',
          type: 'error',
          context: 'product',
        };
        handleRequisitionListAlert(alertPayload);
        events.emit('requisitionList/alert', alertPayload);
      } finally {
        setAddingToCartItemId(null);
        setBulkAddingToCart(false);
      }
    },
    [currentRequisitionList, handleRequisitionListAlert, translations]
  );

  const handleDeleteItems = useCallback((itemUids: string[] | undefined) => {
    if (itemUids && itemUids.length > 0) {
      setItemsToDelete(itemUids);
      setShowDeleteModal(true);
    }
  }, []);

  const handleConfirmDelete = useCallback(async () => {
    if (itemsToDelete.length === 1) {
      setDeletingItemId(itemsToDelete[0]);
    } else {
      setDeletingItemId('bulk');
    }

    try {
      const updatedRequisitionList = await deleteRequisitionListItems(
        currentRequisitionList.uid,
        itemsToDelete,
        currentPageSize,
        currentRequisitionList.page_info.current_page,
        enrichConfigurableProducts
      );

      if (updatedRequisitionList) {
        // Enrich configurable products
        const enrichedWithConfigurable = await enrichConfigurableProductsInList(
          updatedRequisitionList
        );
        // Fetch and merge product data to ensure prices are loaded
        const enrichedRequisitionList = await fetchAndMergeProducts(
          enrichedWithConfigurable
        );
        setCurrentRequisitionList(enrichedRequisitionList);
        handleRequisitionListAlert({
          action: 'delete',
          type: 'success',
          context: 'product',
        });
      } else {
        handleRequisitionListAlert({
          action: 'delete',
          type: 'error',
          context: 'product',
        });
      }
    } catch (error) {
      handleRequisitionListAlert({
        action: 'delete',
        type: 'error',
        context: 'product',
      });
    } finally {
      setDeletingItemId(null);
      setShowDeleteModal(false);
      setItemsToDelete([]);
    }
  }, [
    itemsToDelete,
    currentRequisitionList,
    currentPageSize,
    fetchAndMergeProducts,
    setCurrentRequisitionList,
    handleRequisitionListAlert,
    enrichConfigurableProductsInList,
    enrichConfigurableProducts,
  ]);

  const handleUpdateQuantity = useCallback(
    async (itemUid: string, newQuantity: number) => {
      setUpdatingQuantityItemId(itemUid);

      try {
        // Find the current item to update
        const currentItem = currentRequisitionList.items?.find(
          (item: Item) => item.uid === itemUid
        );
        if (!currentItem) {
          handleRequisitionListAlert({
            action: 'update',
            type: 'error',
            context: 'product',
          });
          return;
        }

        // Create updated item with new quantity
        const updatedItem = {
          item_id: currentItem.uid,
          entered_options: currentItem.entered_options,
          selected_options: currentItem.selected_options,
          quantity: newQuantity,
        };

        const updatedRequisitionList = await updateRequisitionListItems(
          currentRequisitionList.uid,
          [updatedItem],
          currentPageSize,
          currentRequisitionList.page_info.current_page,
          enrichConfigurableProducts
        );

        if (updatedRequisitionList) {
          // List already enriched via updateRequisitionListItems(enrichConfigurableProducts)
          const enrichedRequisitionList = await fetchAndMergeProducts(
            updatedRequisitionList
          );
          setCurrentRequisitionList(enrichedRequisitionList);
          handleRequisitionListAlert({
            action: 'update',
            type: 'success',
            context: 'product',
          });
        } else {
          handleRequisitionListAlert({
            action: 'update',
            type: 'error',
            context: 'product',
          });
        }
      } catch (error) {
        handleRequisitionListAlert({
          action: 'update',
          type: 'error',
          context: 'product',
        });
      } finally {
        setUpdatingQuantityItemId(null);
      }
    },
    [
      currentRequisitionList,
      fetchAndMergeProducts,
      setCurrentRequisitionList,
      currentPageSize,
      handleRequisitionListAlert,
      enrichConfigurableProducts,
    ]
  );

  const handlePageChange = useCallback(
    async (page: number) => {
      setLoadingPage(true);

      try {
        const updatedRequisitionList = await getRequisitionList(
          currentRequisitionList.uid,
          page,
          currentPageSize,
          enrichConfigurableProducts
        );

        if (updatedRequisitionList) {
          // Fetch product data for the new page (list already enriched via getRequisitionList)
          const enrichedWithConfigurable = updatedRequisitionList;
          const updatedListWithProducts = await fetchAndMergeProducts(
            enrichedWithConfigurable
          );
          setCurrentRequisitionList(updatedListWithProducts);
        } else {
          console.warn(translations.errorLoadPage);
        }
      } catch (error) {
        console.warn(
          error instanceof Error ? error.message : translations.errorLoadPage
        );
      } finally {
        setLoadingPage(false);
      }
    },
    [
      currentRequisitionList?.uid,
      fetchAndMergeProducts,
      currentPageSize,
      translations,
      setCurrentRequisitionList,
      enrichConfigurableProducts,
    ]
  );

  const handlePageSizeChange = useCallback(
    async (newPageSize: number) => {
      setCurrentPageSize(newPageSize);
      setLoadingPage(true);

      try {
        // Reset to page 1 when changing page size
        const updatedRequisitionList = await getRequisitionList(
          currentRequisitionList.uid,
          1,
          newPageSize,
          enrichConfigurableProducts
        );

        if (updatedRequisitionList) {
          // Fetch product data for the new page (list already enriched via getRequisitionList)
          const enrichedWithConfigurable = updatedRequisitionList;
          const updatedListWithProducts = await fetchAndMergeProducts(
            enrichedWithConfigurable
          );
          setCurrentRequisitionList(updatedListWithProducts);
        } else {
          console.warn(translations.errorLoadPage);
        }
      } catch (error) {
        console.warn(translations.errorLoadPage);
      } finally {
        setLoadingPage(false);
      }
    },
    [
      currentRequisitionList?.uid,
      fetchAndMergeProducts,
      translations,
      setCurrentRequisitionList,
      enrichConfigurableProducts,
    ]
  );

  const handleUpdate = useCallback(
    async (updatedList: RequisitionList) => {
      // Enrich configurable products
      const enrichedWithConfigurable = await enrichConfigurableProductsInList(
        updatedList
      );
      // With the updated API, the response includes items and page_info
      // but we need to fetch and merge full product data (prices, images, etc.)
      const enrichedList = await fetchAndMergeProducts(
        enrichedWithConfigurable
      );
      setCurrentRequisitionList(enrichedList);
    },
    [
      setCurrentRequisitionList,
      fetchAndMergeProducts,
      enrichConfigurableProductsInList,
    ]
  );

  return (
    <div className="requisition-list-view__container">
      {initializing ? (
        <div className="requisition-list-view__loading">
          <ProgressSpinner stroke={'4'} size={'large'} />
        </div>
      ) : isEnabled === false ? (
        <NotFound
          title={translations.notEnabledTitle}
          message={translations.notEnabledMessage}
          actionLabel={translations.notEnabledActionLabel}
          onAction={() => {
            window.location.href = fallbackRoute;
          }}
        />
      ) : !currentRequisitionList ||
        !isValidBase64Uid(currentRequisitionList?.uid) ? (
        <NotFound
          title={translations.notFoundTitle}
          message={translations.notFoundMessage}
          actionLabel={
            routeRequisitionListGrid
              ? translations.notFoundActionLabel
              : undefined
          }
          onAction={
            routeRequisitionListGrid
              ? () => {
                  const url = routeRequisitionListGrid();
                  if (url && typeof url === 'string') {
                    window.location.href = url;
                  }
                }
              : undefined
          }
        />
      ) : (
        <>
          <RequisitionListHeader
            requisitionList={currentRequisitionList}
            routeRequisitionListGrid={routeRequisitionListGrid}
            onUpdate={handleUpdate}
            onAlert={handleRequisitionListAlert}
            enrichConfigurableProducts={enrichConfigurableProducts}
            currentCustomerEmail={currentCustomerEmail}
            routeSharedRequisitionList={routeSharedRequisitionList}
          />

          {alert && (
            <div className="requisition-list__alert-wrapper">
              <InLineAlert
                heading={alert.description}
                type={alert.type}
                variant="primary"
                onDismiss={() => setAlert(null)}
              />
            </div>
          )}

          {currentRequisitionList.items_count === 0 ? (
            <EmptyList
              textContent={`${currentRequisitionList.name} ${translations.emptyRequisitionList}`}
            />
          ) : (
            <>
              <BatchActions
                selectedItems={selectedItems}
                deletingItemId={deletingItemId}
                addingToCartItemId={addingToCartItemId}
                bulkAddingToCart={bulkAddingToCart}
                updatingQuantityItemId={updatingQuantityItemId}
                bulkMovingToList={movingToList}
                bulkCopyingToList={copyingToList}
                onSelectAll={handleSelectAll}
                onSelectNone={handleSelectNone}
                onBulkAddToCart={() =>
                  handleAddItemsToCart(Array.from(selectedItems))
                }
                onBulkDelete={() =>
                  handleDeleteItems(Array.from(selectedItems))
                }
                onBulkMoveToList={() => setShowMoveToListModal(true)}
                onBulkCopyToList={() => setShowCopyToListModal(true)}
              />

              <ProductListTable
                items={currentRequisitionList.items}
                selectedItems={selectedItems}
                currentPage={
                  currentRequisitionList.page_info?.current_page || 1
                }
                pageSize={
                  currentRequisitionList.page_info?.page_size ||
                  DEFAULT_PAGE_SIZE
                }
                handleItemSelection={handleItemSelection}
                handleUpdateQuantity={handleUpdateQuantity}
                onAddToCart={handleAddItemsToCart}
                onDeleteItem={handleDeleteItems}
              />

              {/* Pagination */}
              {currentRequisitionList.page_info && (
                <div className="requisition-list-view__pagination">
                  <PaginationItemsCounter
                    pageInfo={currentRequisitionList.page_info}
                    totalCount={currentRequisitionList.items_count}
                  />
                  {(currentRequisitionList.page_info?.total_pages || 0) > 1 && (
                    <Pagination
                      totalPages={currentRequisitionList.page_info.total_pages}
                      currentPage={
                        currentRequisitionList.page_info?.current_page || 1
                      }
                      onChange={handlePageChange}
                      disabled={loadingPage || loadingProducts}
                    />
                  )}
                  <div className="requisition-list-view__pagination-picker">
                    <span>{translations.show}</span>
                    <PageSizePicker
                      currentPageSize={
                        currentRequisitionList.page_info?.page_size ||
                        DEFAULT_PAGE_SIZE
                      }
                      onPageSizeChange={handlePageSizeChange}
                      disabled={loadingPage || loadingProducts}
                    />
                  </div>
                </div>
              )}
            </>
          )}
        </>
      )}

      {/* Delete Confirmation Modal */}
      {showDeleteModal && (
        <RequisitionListModal
          isOpen={showDeleteModal}
          isLoading={deletingItemId !== null}
          title={translations.deleteItemsTitle}
          modalContent={translations.deleteItemsMessage}
          confirmBtnCaption={translations.confirmAction}
          closeBtnCaption={translations.cancelAction}
          handleModalOnClose={() => {
            setShowDeleteModal(false);
            setItemsToDelete([]);
          }}
          handleModalOnConfirm={handleConfirmDelete}
        />
      )}

      {/* Move to Requisition List Modal */}
      {showMoveToListModal && (
        <RequisitionListModal
          isOpen={showMoveToListModal}
          isLoading={movingToList}
          title={translations.moveToListTitle}
          modalContent={
            <RequisitionListPicker
              excludeUid={currentRequisitionList?.uid}
              confirmLabel={translations.moveToListConfirm}
              disabled={movingToList}
              onConfirm={handleMoveToList}
            />
          }
          handleModalOnClose={() => setShowMoveToListModal(false)}
        />
      )}

      {/* Copy to Requisition List Modal */}
      {showCopyToListModal && (
        <RequisitionListModal
          isOpen={showCopyToListModal}
          isLoading={copyingToList}
          title={translations.copyToListTitle}
          modalContent={
            <RequisitionListPicker
              excludeUid={currentRequisitionList?.uid}
              confirmLabel={translations.copyToListConfirm}
              disabled={copyingToList}
              onConfirm={handleCopyToList}
            />
          }
          handleModalOnClose={() => setShowCopyToListModal(false)}
        />
      )}
    </div>
  );
};
