import { useState, useCallback } from 'preact/hooks';
import { Container } from '@adobe-commerce/elsie/lib';
import { useText } from '@adobe-commerce/elsie/i18n';
import { RequisitionListHeader as RequisitionListHeaderComponent } from '@/requisitionList/components/RequisitionListHeader/RequisitionListHeader';
import { RequisitionListForm } from '@/requisitionList/components/RequisitionListForm/RequisitionListForm';
import { RequisitionListModal } from '@/requisitionList/components/RequisitionListModal/RequisitionListModal';
import { updateRequisitionList } from '@/requisitionList/api/updateRequisitionList';
import { deleteRequisitionList } from '@/requisitionList/api/deleteRequisitionList';
import {
  shareRequisitionListByEmail,
  ShareRequisitionListByEmailError,
} from '@/requisitionList/api/shareRequisitionListByEmail';
import { RequisitionList } from '@/requisitionList/data/models/requisitionList';
import { Item } from '@/requisitionList/data/models/item';
import { ShareRequisitionListContent } from '@/requisitionList/containers/ShareRequisitionListContent';
import { state } from '@/requisitionList/lib/state';

export interface RequisitionListHeaderProps {
  requisitionList: RequisitionList;
  routeRequisitionListGrid?: () => string | void;
  onUpdate?: (updatedList: RequisitionList) => void | Promise<void>;
  onAlert?: (payload: {
    action: string;
    type: string;
    context: string;
  }) => void;
  enrichConfigurableProducts?: (items: Item[]) => Promise<Item[]>;
  currentCustomerEmail?: string;
  routeSharedRequisitionList?: (relativeUrl: string) => string;
}

export const RequisitionListHeader: Container<RequisitionListHeaderProps> = ({
  requisitionList,
  routeRequisitionListGrid,
  onUpdate,
  onAlert,
  enrichConfigurableProducts,
  currentCustomerEmail,
  routeSharedRequisitionList,
}: RequisitionListHeaderProps) => {
  const [showRenameModal, setShowRenameModal] = useState<boolean>(false);
  const [showDeleteModal, setShowDeleteModal] = useState<boolean>(false);
  const [showShareModal, setShowShareModal] = useState<boolean>(false);
  const [isDeleting, setIsDeleting] = useState<boolean>(false);
  const [isSharing, setIsSharing] = useState<boolean>(false);
  const sharingConfigValue = state.config?.requisition_list_sharing_enabled;
  const isShareEnabled =
    sharingConfigValue !== false && sharingConfigValue !== '0';
  const itemsCount = Number(
    requisitionList.items_count ?? requisitionList.items?.length ?? 0
  );
  const isShareDisabled = itemsCount <= 0 || !state.isCompanyUser;

  const translations = useText({
    actionBackToRequisitionLists: `RequisitionList.RequisitionListView.actionBackToRequisitionLists`,
    actionRename: `RequisitionList.RequisitionListView.actionRename`,
    actionDeleteList: `RequisitionList.RequisitionListView.actionDeleteList`,
    actionShare: `RequisitionList.RequisitionListView.actionShare`,
    shareDisabledReason: `RequisitionList.RequisitionListView.shareDisabledReason`,
    shareDisabledNoCompany: `RequisitionList.RequisitionListView.shareDisabledNoCompany`,
    shareListTitle: `RequisitionList.RequisitionListView.shareListTitle`,
    deleteListTitle: `RequisitionList.RequisitionListView.deleteListTitle`,
    deleteListMessage: `RequisitionList.RequisitionListView.deleteListMessage`,
    confirmAction: `RequisitionList.RequisitionListWrapper.confirmAction`,
    cancelAction: `RequisitionList.RequisitionListWrapper.cancelAction`,
    updateTitle: `RequisitionList.RequisitionListForm.updateTitle`,
  });

  const handleRename = useCallback(() => {
    setShowRenameModal(true);
  }, []);

  const handleRenameSubmit = useCallback(
    async (values: { name: string; description?: string }) => {
      try {
        const updatedList = await updateRequisitionList(
          requisitionList.uid,
          values.name,
          values.description,
          requisitionList.page_info?.page_size,
          requisitionList.page_info?.current_page,
          enrichConfigurableProducts
        );
        if (updatedList) {
          onUpdate?.(updatedList);
          setShowRenameModal(false);
          onAlert?.({
            action: 'update',
            type: 'success',
            context: 'requisitionList',
          });
        } else {
          onAlert?.({
            action: 'update',
            type: 'error',
            context: 'requisitionList',
          });
        }
      } catch (error) {
        onAlert?.({
          action: 'update',
          type: 'error',
          context: 'requisitionList',
        });
      }
    },
    [
      requisitionList.uid,
      requisitionList.page_info,
      onUpdate,
      onAlert,
      enrichConfigurableProducts,
    ]
  );

  const handleDeleteList = useCallback(() => {
    setShowDeleteModal(true);
  }, []);

  const handleDeleteConfirm = useCallback(async () => {
    setIsDeleting(true);
    try {
      const result = await deleteRequisitionList(requisitionList.uid);
      if (result) {
        const alertPayload = {
          action: 'delete',
          type: 'success',
          context: 'requisitionList',
        };

        // Store alert in localStorage before redirecting
        // This ensures the alert is shown after redirect to grid view
        try {
          localStorage.setItem(
            'requisitionListPendingAlert',
            JSON.stringify(alertPayload)
          );
        } catch (e) {
          // Ignore localStorage errors (e.g., in private browsing mode)
        }

        if (routeRequisitionListGrid) {
          const url = routeRequisitionListGrid();
          // If a URL is returned, navigate to it
          if (url && typeof url === 'string') {
            window.location.href = url;
          }
        }
      } else {
        onAlert?.({
          action: 'delete',
          type: 'error',
          context: 'requisitionList',
        });
      }
    } catch (error) {
      onAlert?.({
        action: 'delete',
        type: 'error',
        context: 'requisitionList',
      });
    } finally {
      setIsDeleting(false);
      setShowDeleteModal(false);
    }
  }, [requisitionList.uid, routeRequisitionListGrid, onAlert]);

  const handleShare = useCallback(() => {
    setShowShareModal(true);
  }, []);

  const handleShareSubmit = useCallback(
    async (
      customerUids: string[]
    ): Promise<Array<ShareRequisitionListByEmailError> | null> => {
      setIsSharing(true);
      try {
        const errors = await shareRequisitionListByEmail(
          requisitionList.uid,
          customerUids
        );
        return errors;
      } catch {
        return [{ code: 'SHARE_FAILED', message: 'Unable to share list.' }];
      } finally {
        setIsSharing(false);
      }
    },
    [requisitionList.uid]
  );

  return (
    <>
      <RequisitionListHeaderComponent
        name={requisitionList.name}
        description={requisitionList.description}
        backLink={
          routeRequisitionListGrid
            ? {
                url: '#',
                label: translations.actionBackToRequisitionLists,
                onClick: (e: Event) => {
                  e.preventDefault();
                  const result = routeRequisitionListGrid();
                  // If a URL is returned, navigate to it
                  if (result && typeof result === 'string') {
                    window.location.href = result;
                  }
                },
              }
            : undefined
        }
        actions={{
          onRename: handleRename,
          onDelete: handleDeleteList,
          onShare: isShareEnabled && !isShareDisabled ? handleShare : undefined,
          renameLabel: translations.actionRename,
          deleteLabel: translations.actionDeleteList,
          shareLabel: isShareEnabled ? translations.actionShare : undefined,
          shareDisabled: isShareEnabled && isShareDisabled,
          shareDisabledReason:
            isShareEnabled && isShareDisabled
              ? itemsCount <= 0
                ? translations.shareDisabledReason
                : translations.shareDisabledNoCompany
              : undefined,
        }}
      />

      {/* Rename Modal */}
      {showRenameModal && (
        <RequisitionListModal
          isOpen={showRenameModal}
          isLoading={false}
          title={translations.updateTitle}
          modalContent={
            <RequisitionListForm
              mode="update"
              defaultValues={{
                name: requisitionList.name,
                description: requisitionList.description || '',
              }}
              onSubmit={handleRenameSubmit}
              onCancel={() => setShowRenameModal(false)}
            />
          }
          handleModalOnClose={() => setShowRenameModal(false)}
        />
      )}

      {/* Delete Confirmation Modal */}
      {showDeleteModal && (
        <RequisitionListModal
          isOpen={showDeleteModal}
          isLoading={isDeleting}
          title={translations.deleteListTitle}
          modalContent={translations.deleteListMessage}
          confirmBtnCaption={translations.confirmAction}
          closeBtnCaption={translations.cancelAction}
          handleModalOnClose={() => setShowDeleteModal(false)}
          handleModalOnConfirm={handleDeleteConfirm}
        />
      )}

      {/* Share Modal */}
      {isShareEnabled && showShareModal && (
        <RequisitionListModal
          isOpen={showShareModal}
          isLoading={isSharing}
          title={translations.shareListTitle}
          modalContent={
            <ShareRequisitionListContent
              requisitionListUid={requisitionList.uid}
              isSubmitting={isSharing}
              onSubmit={handleShareSubmit}
              currentCustomerEmail={currentCustomerEmail}
              routeSharedRequisitionList={routeSharedRequisitionList}
            />
          }
          handleModalOnClose={() => setShowShareModal(false)}
        />
      )}
    </>
  );
};
